/**
 * Shared implementation for two-finger pinch zoom and map rotation.
 * 
 * @see https://github.com/fnicollet/Leaflet/commit/a77af51a6b10f308d1b9a16552091d1d0aee8834
 * @see https://github.com/Leaflet/Leaflet/blob/v1.9.3/src/map/handler/Map.TouchZoom.js
 * 
 * @typedef L.Map.TouchGestures
 * @property {boolean} [bounceAtZoomLimits] Whether pinch zoom may temporarily exceed zoom limits.
 * @property {boolean} zoom Whether pinch zoom is enabled.
 * @property {boolean} rotate Whether touch rotation is enabled.
 * 
 * @since leaflet-rotate (v0.1.0)
 */

/**
 * Convert a touch's client coordinates to coordinates relative to the map container.
 * 
 * @param {L.Map} map
 * @param {Touch} touch
 * 
 * @returns {L.Point}
 * 
 * @since leaflet-rotate (v0.1.0)
 */
import { L } from './L.js';

const zoomOption = L.version.startsWith('2.') ? 'pinchZoom' : 'touchZoom';

function touchToContainerPoint(map, touch) {
    const container = map.getContainer(),
        rect = container.getBoundingClientRect();

    return new L.Point(
        touch.clientX - rect.left - container.clientLeft,
        touch.clientY - rect.top - container.clientTop,
    );
}

L.Map.mergeOptions({

    /**
     * Whether pinch zoom may temporarily exceed min/max zoom and bounce back.
     * 
     * @type {Boolean}
     * 
     * @since leaflet-rotate (v0.1.0)
     */
    bounceAtZoomLimits: true,

});

L.Map.TouchGestures = class extends L.Handler {

    /**
     * Initialize the shared handler from the map's touch zoom/rotation options.
     * 
     * @param {L.Map} map Map whose touch gestures are handled.
     * 
     * @since leaflet-rotate (v0.1.0)
     */
    constructor(map) {
        super(map);
        this.rotate = !!this._map.options.touchRotate;
        this.zoom = !!this._map.options[zoomOption];
        this.pitch = !!this._map.options.touchPitch;
    }
};

L.Map.TouchGestures.include({
    /**
     * Listen for the start of two-finger gestures on the map container.
     * 
     * @since leaflet-rotate (v0.1.0)
     */
    addHooks() {
        const container = this._map._container;
        if (L.version.startsWith('2.')) {
            this._pointers = new Map();
            L.DomEvent.on(container, 'pointerdown', this._onPointerDown, this);
            L.DomEvent.on(container, 'pointermove', this._onPointerMove, this);
            L.DomEvent.on(container, 'pointerup pointercancel lostpointercapture', this._onPointerUp, this);
        } else {
            L.DomEvent.on(container, 'touchstart', this._onTouchStart, this);
        }
    },

    /**
     * Remove the touch-start listener.
     * 
     * @since leaflet-rotate (v0.1.0)
     */
    removeHooks() {
        const container = this._map._container;
        L.DomEvent.off(container, 'touchstart', this._onTouchStart, this);
        L.DomEvent.off(container, 'pointerdown', this._onPointerDown, this);
        L.DomEvent.off(container, 'pointermove', this._onPointerMove, this);
        L.DomEvent.off(container, 'pointerup pointercancel lostpointercapture', this._onPointerUp, this);
        cancelAnimationFrame(this._gestureFrame);
        this._gestureFrame = null;
        if (this._pointers) this._pointers.clear();
        this._onTouchEnd();
    },

    _pointerTouches(e) {
        return {
            touches: [...this._pointers.values()],
            preventDefault: () => e.preventDefault(),
        };
    },

    _onPointerDown(e) {
        if (e.pointerType === 'mouse') { return; }
        this._pointers.set(e.pointerId, e);
        this._onTouchStart(this._pointerTouches(e));
    },

    _onPointerMove(e) {
        if (!this._pointers.has(e.pointerId)) { return; }
        this._pointers.set(e.pointerId, e);
        if (!this._gesture) { return; }
        e.preventDefault();
        // Coalesce the two fingers' separate pointer events before classifying the gesture.
        if (!this._gestureFrame) {
            this._gestureFrame = requestAnimationFrame(() => {
                this._gestureFrame = null;
                this._onTouchMove(this._pointerTouches(e));
            });
        }
    },

    _onPointerUp(e) {
        if (e.type === 'lostpointercapture' && e.buttons) { return; }
        if (!this._pointers.has(e.pointerId)) { return; }
        if (this._gestureFrame) {
            cancelAnimationFrame(this._gestureFrame);
            this._gestureFrame = null;
            this._onTouchMove(this._pointerTouches(e));
        }
        this._pointers.delete(e.pointerId);
        if (this._pointers.size < 2) this._onTouchEnd();
    },

    /**
     * Record initial touch points and start tracking a two-finger gesture.
     * 
     * @param {TouchEvent} e Touch-start event.
     * 
     * @since leaflet-rotate (v0.1.0)
     */
    _onTouchStart(e) {
        const map = this._map;

        if (!e.touches || e.touches.length !== 2 || map._animatingZoom || this._zooming || this._rotating || this._gesture) { return; }

        const p1 = touchToContainerPoint(map, e.touches[0]),
            p2 = touchToContainerPoint(map, e.touches[1]),
            vector = p1.subtract(p2);

        // Two horizontally aligned fingers moving vertically together change the pitch
        const canPitch = this.pitch && map._rotate && Math.abs(vector.x) > Math.abs(vector.y);
        if (!canPitch && !this.zoom && !this.rotate) { return; }
        this._gesture = canPitch ? 'pending' : 'pinch';
        this._startP1 = p1;
        this._startP2 = p2;
        map._stopPitchBearingAnimation();

        this._centerPoint = map.getSize()._divideBy(2);
        this._startLatLng = map.containerPointToLatLng(this._centerPoint);

        if (this.zoom) {
            if (map.options[zoomOption] !== 'center') {
                this._pinchStartLatLng = map.containerPointToLatLng(p1.add(p2)._divideBy(2));
            }
            this._startDist = p1.distanceTo(p2);
            this._startZoom = map.getZoom();
            this._zooming = true;
        } else {
            this._zooming = false;
        }

        if (this.rotate) {
            this._startTheta = Math.atan(vector.x / vector.y);
            this._startBearing = map.getBearing();
            if (vector.y < 0) { this._startBearing += 180; }
            this._rotating = true;
        } else {
            this._rotating = false;
        }

        this._moved = false;

        map._stop();

        if (!L.version.startsWith('2.')) {
            L.DomEvent.on(document, 'touchmove', this._onTouchMove, this);
            L.DomEvent.on(document, 'touchend touchcancel', this._onTouchEnd, this);
        }

        L.DomEvent.preventDefault(e);
    },

    /**
     * Update bearing and/or zoom while the two touch points move.
     * 
     * @param {TouchEvent} e Touch-move event.
     * 
     * @since leaflet-rotate (v0.1.0)
     */
    _onTouchMove(e) {
        if (!e.touches || e.touches.length !== 2 || !this._gesture) { return; }

        const map = this._map,
            p1 = touchToContainerPoint(map, e.touches[0]),
            p2 = touchToContainerPoint(map, e.touches[1]),
            vector = p1.subtract(p2),
            scale = p1.distanceTo(p2) / this._startDist;
        let delta;

        if (this._gesture === 'pending') {
            const d1 = p1.subtract(this._startP1),
                d2 = p2.subtract(this._startP2);
            if (Math.max(d1.x * d1.x + d1.y * d1.y, d2.x * d2.x + d2.y * d2.y) < 25) {
                L.DomEvent.preventDefault(e);
                return;
            }
            const vertical = d => Math.abs(d.y) > Math.abs(d.x);
            if (vertical(d1) && vertical(d2) && Math.sign(d1.y) === Math.sign(d2.y)) {
                this._gesture = 'pitch';
                this._lastPitchY = (this._startP1.y + this._startP2.y) / 2;
                this._zooming = this._rotating = false;
            } else {
                this._gesture = 'pinch';
            }
        }

        if (this._gesture === 'pitch') {
            const y = (p1.y + p2.y) / 2;
            map._setPitchAndBearing(map.getPitch() - (y - this._lastPitchY) * 0.5, map.getBearing());
            this._lastPitchY = y;
            L.DomEvent.preventDefault(e);
            return;
        }

        if (!(this._zooming || this._rotating)) { return; }

        if (this._rotating) {
            const theta = Math.atan(vector.x / vector.y);
            let bearingDelta = (theta - this._startTheta) * (180 / Math.PI);
            if (vector.y < 0) { bearingDelta += 180; }
            if (bearingDelta) {
                /**
                 * @TODO the pivot should be the last touch point,
                 * but zoomAnimation manages to overwrite the rotate
                 * pane position. Maybe related to #3529.
                 * 
                 * @see https://github.com/Leaflet/Leaflet/pull/3529
                 * @see https://github.com/fnicollet/Leaflet/commit/a77af51a6b10f308d1b9a16552091d1d0aee8834
                 */
                map.setBearing(this._startBearing - bearingDelta);
            }
        }

        if (this._zooming) {
            this._zoom = map.getScaleZoom(scale, this._startZoom);

            if (!map.options.bounceAtZoomLimits && (
                    (this._zoom < map.getMinZoom() && scale < 1) ||
                    (this._zoom > map.getMaxZoom() && scale > 1))) {
                this._zoom = map._limitZoom(this._zoom);
            }

            if (map.options[zoomOption] === 'center') {
                this._center = this._startLatLng;
                if (scale === 1) { return; }
            } else {
                // Get delta from pinch to center, so centerLatLng is delta applied to initial pinchLatLng
                delta = p1._add(p2)._divideBy(2)._subtract(this._centerPoint);
                if (scale === 1 && delta.x === 0 && delta.y === 0) { return; }

                const mapDelta = map._pitch
                    ? map.containerPointToLayerPoint(this._centerPoint.add(delta))
                        .subtract(map.containerPointToLayerPoint(this._centerPoint))
                    : delta.rotate(-map.getBearing() * (Math.PI / 180));

                this._center = map.unproject(map.project(this._pinchStartLatLng).subtract(mapDelta));
            }

        }

        if (!this._moved) {
            map._moveStart(true, false);
            this._moved = true;
        }

        const moveFn = map._move.bind(map, this._center, this._zoom, { pinch: true, round: false }, undefined);
        moveFn();

        if (this.zoom) {
            if (map.options.zoomAnimation) {
                map._animateZoomNoDelay(this._center, map._limitZoom(this._zoom));
            } else {
                map._resetView(this._center, map._limitZoom(this._zoom));
            }
        }

        L.DomEvent.preventDefault(e);
    },

    /**
     * Finish the gesture, settle the zoom and remove document listeners.
     * 
     * @since leaflet-rotate (v0.1.0)
     */
    _onTouchEnd() {
        const gesture = this._gesture;
        delete this._gesture;
        if (gesture === 'pitch' || gesture === 'pending' || !this._moved || !(this._zooming || this._rotating)) {
            this._zooming = false;
            this._rotating = false;
            L.DomEvent.off(document, 'touchmove', this._onTouchMove, this);
            L.DomEvent.off(document, 'touchend touchcancel', this._onTouchEnd, this);
            return;
        }

        this._zooming = false;
        this._rotating = false;
        L.DomEvent.off(document, 'touchmove', this._onTouchMove, this);
        L.DomEvent.off(document, 'touchend touchcancel', this._onTouchEnd, this);

        if (this.zoom) {
            // Pinch updates GridLayers' levels only when zoomSnap is off, so zoomSnap becomes noUpdate.
            if (this._map.options.zoomAnimation) {
                this._map._animateZoom(this._center, this._map._limitZoom(this._zoom), true, this._map.options.zoomSnap);
            } else {
                this._map._resetView(this._center, this._map._limitZoom(this._zoom));
            }
        }
    },

});

/**
 * Add the shared touch gesture handler to the map.
 * 
 * @property {L.Map.TouchGestures} touchGestures
 * 
 * @since leaflet-rotate (v0.1.0)
 */
L.Map.addInitHook('addHandler', 'touchGestures', L.Map.TouchGestures);
